package com.nanless.paperdigest.cloud
import org.json.*
import org.junit.Assert.*
import org.junit.Test
import java.io.File
import java.nio.file.Files
import java.util.concurrent.CancellationException
class RestoreCancellationTest {
 private fun personal(endpoint:String)=JSONObject().put("schema",1).put("notes",JSONObject()).put("settings",JSONObject().put("endpoint",endpoint).put("model","fixture").put("dailyRequests",5)).put("favorites",JSONArray()).put("reading",JSONArray()).put("readingState",JSONObject()).put("annotations",JSONObject()).put("sessions",JSONArray()).put("jobs",JSONArray())
 private fun temp(body:(File)->Unit){val p=Files.createTempDirectory("restore-cancel-").toRealPath().toFile();try{body(p)}finally{p.deleteRecursively()}}
 private fun root(p:File,name:String)=File(p,name).apply{mkdir();File(this,"personal.json").writeText(personal("https://$name.invalid/v1").toString());File(this,"large").writeBytes(ByteArray(300000){(it%251).toByte()})}
 private fun captureStage(p:File,incoming:File)=BackupCodec.capture(incoming,File(p,"original.paperdigest")).let{BackupCodec.stage(it.file.inputStream(),p)}
 private fun files(p:File)=p.walkTopDown().filter{it.isFile}.associate{it.relativeTo(p).path to BackupCodec.hash(it)}
 @Test fun cancelledEffectiveCopyPreservesPreflightAndLiveBytesForSameStageRetry()=temp{p->val live=root(p,"Live");val incoming=root(p,"Incoming");File(incoming,"remote-only").writeText("remote");val stage=captureStage(p,incoming);val beforeLive=files(live);val beforeStage=files(stage.directory);var checks=0;val error=runCatching{RestorePolicy.install(stage,live,initialize={error("Must not initialize")},check={if(++checks==12)throw CancellationException()})}.exceptionOrNull();assertTrue(error is CancellationException);assertEquals(beforeLive,files(live));assertEquals(beforeStage,files(stage.directory));assertFalse(p.listFiles()!!.any{it.name.startsWith(".effective-restore-")});var reloads=0;val retained=RestorePolicy.install(stage,live,initialize={reloads++},check={});assertEquals(1,reloads);assertEquals(beforeLive,files(retained));assertEquals("remote",File(live,"remote-only").readText());assertEquals("https://Live.invalid/v1",JSONObject(File(live,"personal.json").readText()).getJSONObject("settings").getString("endpoint"));assertFalse(stage.directory.exists())}
 @Test fun initialiseFailureRollsBackOldLiveAndRetainsOriginalPreflight()=temp{p->val live=root(p,"Live");val stage=captureStage(p,root(p,"Incoming"));val beforeLive=files(live);val beforeStage=files(stage.directory);var calls=0;assertTrue(runCatching{RestorePolicy.install(stage,live,initialize={if(++calls==1)error("synthetic initialization failure")},check={})}.isFailure);assertEquals(2,calls);assertEquals(beforeLive,files(live));assertEquals(beforeStage,files(stage.directory));assertTrue(p.listFiles()!!.any{it.name.startsWith("Live-FailedRestore-")})}
 @Test fun stageMutationAndExtraFileFailBeforeLiveRenameWithoutDeletingEvidence()=temp{p->val live=root(p,"Live");val stage=captureStage(p,root(p,"Incoming"));val before=files(live);File(stage.directory,"unexpected").writeText("keep");assertTrue(runCatching{RestorePolicy.install(stage,live,initialize={})}.isFailure);assertEquals(before,files(live));assertEquals("keep",File(stage.directory,"unexpected").readText());File(stage.directory,"unexpected").delete();File(stage.directory,"large").appendText("changed");assertTrue(runCatching{RestorePolicy.install(stage,live,initialize={})}.isFailure);assertEquals(before,files(live));assertTrue(File(stage.directory,"large").length()>300000)}
 @Test fun atomicCommitDoesNotRunCallerCancellationBetweenRenamesAndInitialise()=temp{p->val live=root(p,"Live");val stage=captureStage(p,root(p,"Incoming"));var checks=0;var countAtInit=-1;var initialized=false;RestorePolicy.install(stage,live,initialize={countAtInit=checks;initialized=true},check={assertFalse("No checks after atomic commit begins",initialized);checks++});assertTrue(initialized);assertEquals(countAtInit,checks)}
}
